import {rosterFor} from './services.js';
import {positions} from './config.js';
function editableRoster(game,setIndex){if(!Number.isInteger(setIndex)||setIndex<0||setIndex>=game.sets.length)throw Error('세트를 선택하세요.');game.setRosters=game.sets.map((_,i)=>structuredClone(game.setRosters?.[i]||game.roster));return game.setRosters[setIndex];}
export function setPlayerPosition(game,setIndex,playerId,position){if(!positions.includes(position))throw Error('포지션을 확인하세요.');const roster=editableRoster(game,setIndex),p=roster.find(p=>p.playerId===playerId);if(!p)throw Error('선수를 찾을 수 없습니다.');p.position=position;}
export function movePlayerRow(game,setIndex,playerId,direction){if(![-1,1].includes(direction))return false;const roster=editableRoster(game,setIndex),ordered=rosterFor(game,setIndex),i=ordered.findIndex(p=>p.playerId===playerId),other=i+direction;if(i<0||!ordered[other])return false;if(ordered[i].role!==ordered[other].role){const a=roster.find(p=>p.playerId===ordered[i].playerId),b=roster.find(p=>p.playerId===ordered[other].playerId);[a.role,b.role]=[ordered[other].role,ordered[i].role];[a.courtPosition,b.courtPosition]=[ordered[other].courtPosition,ordered[i].courtPosition];}[ordered[i],ordered[other]]=[ordered[other],ordered[i]];const order=new Map(ordered.map((p,i)=>[p.playerId,i]));for(const p of roster)p.recordOrder=order.get(p.playerId);return true;}
